import{_ as s,o as t,c as a,a0 as o}from"./chunks/framework.Bzl7znUD.js";const u=JSON.parse('{"title":"How-to: mount a workspace","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/mount.md","filePath":"how-to/mount.md"}'),n={name:"how-to/mount.md"};function i(r,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="how-to-mount-a-workspace" tabindex="-1">How-to: mount a workspace <a class="header-anchor" href="#how-to-mount-a-workspace" aria-label="Permalink to &quot;How-to: mount a workspace&quot;">​</a></h1><p><code>sturn mount</code> exposes a workspace tree as a real filesystem — the interception layer: tools write normally, sturn records ops.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent&#39;s write_file() ──► kernel ──► FUSE ──► SturnFs</span></span>
<span class="line"><span>                                          write() → buffer</span></span>
<span class="line"><span>                                          release → Op::Write → WAL</span></span></code></pre></div><p>FUSE = <em>Filesystem in USErspace</em>: syscalls route to a user process instead of a disk driver, so <code>sturn-fuse</code> decides what &quot;a file&quot; means — ops, not bytes on disk.</p><h2 id="use" tabindex="-1">Use <a class="header-anchor" href="#use" aria-label="Permalink to &quot;Use&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ sturn mount devin /mnt/devin        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># read-only view of the tree</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ sturn mount --rw devin /mnt/devin   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># writes become WAL ops</span></span></code></pre></div><p>Under <code>--rw</code>, plain POSIX writes — <code>echo</code>, editors, build tools, agent <code>write_file</code> — land as <code>Write</code>/<code>Rename</code>/<code>Delete</code> ops with <code>intent: &quot;fuse&quot;</code>. The agent can&#39;t bypass the write path: it <em>is</em> a filesystem, the thing tools already use.</p><h2 id="semantics" tabindex="-1">Semantics <a class="header-anchor" href="#semantics" aria-label="Permalink to &quot;Semantics&quot;">​</a></h2><ul><li><strong>Buffer-then-commit</strong>: <code>write()</code> buffers per open file; the op emits on <code>release</code> (close) or <code>fsync</code> — editors that fsync-per- save get an op at sync point, not just at close.</li><li><strong>Mount-time view</strong>: the tree is the ws tip at mount time — other agents&#39; ops don&#39;t appear live (unmount/remount to see).</li><li><strong>Dirs are implicit</strong> in git trees — <code>mkdir</code>/<code>rmdir</code> are local only; a <code>Write</code> op into the dir is what persists.</li></ul><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$ fusermount -u /mnt/devin</span></span></code></pre></div>`,10)])])}const m=s(n,[["render",i]]);export{u as __pageData,m as default};
